#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, datetime as dt, os, py_compile, shutil, subprocess, sys
from pathlib import Path
VERSION="0.9.0"
MODIFIED_B64={'backend/app/services/vision_app/models.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/runner.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/runtime.py': {'old': '', 'new': ''}, 'frontend/src/Pages/ComputerVisionPage.tsx': {'old': '', 'new': ''}, 'frontend/src/api/visionAppApi.ts': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/CameraModulePanel.tsx': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/IotModulePanel.tsx': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/MasterSamplePanel.tsx': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/WorkingModulePanel.tsx': {'old': '', 'new': ''}, 'frontend/tools/generate_llm_context_map.py': {'old': '', 'new': ''}}
CREATED_B64={'backend/app/services/vision_app/control_runtime.py': '', 'backend/tests/vision_app/test_vision_app_v0900.py': '', 'frontend/docs/llm_context/updates/v0900_computer_vision_control_workspace.md': '', 'frontend/src/components/ComputerVision/DebugWorkspace.tsx': '', 'frontend/src/components/ComputerVision/IotIdePlaceholder.tsx': ''}
MODIFIED={k:{"old":base64.b64decode(v["old"]).decode(),"new":base64.b64decode(v["new"]).decode()} for k,v in MODIFIED_B64.items()}
CREATED={k:base64.b64decode(v).decode() for k,v in CREATED_B64.items()}

def roots(f=None,b=None):
 c=Path.cwd().resolve();fs=[];bs=[]
 if f:fs.append(Path(f).expanduser().resolve())
 if b:bs.append(Path(b).expanduser().resolve())
 fs += [c,c/"LambdaVisionSuper",c.parent/"LambdaVisionSuper"]
 bs += [c,c/"LambdaVisionSuperBackEnd",c.parent/"LambdaVisionSuperBackEnd"]
 fe=next((p for p in fs if (p/"src/Pages/ComputerVisionPage.tsx").exists()),None)
 be=next((p for p in bs if (p/"app/services/vision_app/models.py").exists()),None)
 if not fe: raise RuntimeError("Cannot locate LambdaVisionSuper frontend")
 if not be: raise RuntimeError("Cannot locate LambdaVisionSuperBackEnd")
 return fe,be

def rpath(fe,be,v): return fe/v[9:] if v.startswith("frontend/") else be/v[8:]
def mstate(p,o,n):
 if not p.exists():return "MISSING"
 s=p.read_text(encoding="utf-8")
 return "OK" if s==n else "UPDATE" if s==o else "CONFLICT"
def cstate(p,n):
 if not p.exists():return "CREATE"
 return "OK" if p.read_text(encoding="utf-8")==n else "CONFLICT"
def scan(fe,be):
 print("="*104);print("COMPUTER VISION V0.9.0 — CONTROL MAPPING + WORKSPACE CLEANUP");print("="*104)
 print(f"Frontend : {fe}");print(f"Backend  : {be}\n");bad=0
 for v,x in MODIFIED.items():
  s=mstate(rpath(fe,be,v),x["old"],x["new"]);print(f"  [{s:12}] {v}");bad += s in ("MISSING","CONFLICT")
 for v,n in CREATED.items():
  s=cstate(rpath(fe,be,v),n);print(f"  [{s:12}] {v}");bad += s=="CONFLICT"
 print("\nv0.9 contract:")
 print("  Explicit Original Master recovery after blur preview")
 print("  OK/NG overlay only in Working")
 print("  Working Operation: scope combobox -> larger Filter/Logic detail")
 print("  Dedicated lazy-loaded Debug Workspace")
 print("  Camera-only capture/live-preview viewport")
 print("  IOT center viewport reserved for future IDE/sandbox")
 print("  Control Mapper: Keyboard / Modbus trigger -> primitive actions")
 print("  Decision Edit removed for new v3 programs; future IDE owns decision/glue")
 print("  Context generator + v0.9 handoff MD included")
 if bad:print(f"[WARN] {bad} conflict/base issue(s); apply will stop safely.")
 return 0

def preflight(fe,be):
 e=[]
 for v,x in MODIFIED.items():
  s=mstate(rpath(fe,be,v),x["old"],x["new"])
  if s not in ("UPDATE","OK"):e.append(f"{v}: {s}")
 for v,n in CREATED.items():
  s=cstate(rpath(fe,be,v),n)
  if s not in ("CREATE","OK"):e.append(f"{v}: {s}")
 if e:raise RuntimeError("Safe update stopped:\n  - "+"\n  - ".join(e))
def regen(fe,be):
 g=fe/"tools/generate_llm_context_map.py"
 if not g.exists():print("[SKIP] Context generator not found");return
 cmd=[sys.executable,str(g),"--frontend",str(fe),"--backend",str(be)]
 if "--output-dir" in g.read_text(encoding="utf-8"):cmd += ["--output-dir",str(fe/"docs/llm_context")]
 p=subprocess.run(cmd,cwd=str(fe),text=True,capture_output=True)
 if p.returncode:raise RuntimeError("Context generation failed:\n"+p.stdout+"\n"+p.stderr)
 if p.stdout.strip():print(p.stdout.strip())
def apply(fe,be):
 preflight(fe,be);stamp=dt.datetime.now().strftime("%Y%m%d_%H%M%S");bak=fe/".lambda_updater_backups"/f"computer_vision_v0900_{stamp}";bak.mkdir(parents=True,exist_ok=True)
 for v in list(MODIFIED)+list(CREATED):
  p=rpath(fe,be,v)
  if p.exists():
   q=bak/v;q.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,q)
 for v,x in MODIFIED.items():
  p=rpath(fe,be,v)
  if p.read_text(encoding="utf-8")!=x["new"]:p.write_text(x["new"],encoding="utf-8");print("[WRITE]",v)
 for v,n in CREATED.items():
  p=rpath(fe,be,v);p.parent.mkdir(parents=True,exist_ok=True)
  if not p.exists() or p.read_text(encoding="utf-8")!=n:p.write_text(n,encoding="utf-8");print("[WRITE]",v)
 print("[INFO] Regenerating LLM context docs...");regen(fe,be);print(f"[OK] Backup: {bak}");print("Run verify next.");return 0

def verify(fe,be,skip=False):
 print("="*104);print("VERIFY COMPUTER VISION V0.9.0");print("="*104);fail=0
 checks=[
 ("Program v3 Control Mapper","class ControlMapperConfig" in (be/"app/services/vision_app/models.py").read_text()),
 ("Keyboard + Modbus primitive mapping","actions_for_keyboard" in (be/"app/services/vision_app/control_runtime.py").read_text()),
 ("Runner consults Control Mapper","actions_for_modbus_trigger(program.control)" in (be/"app/services/vision_app/runner.py").read_text()),
 ("Decision ownership reserved for future IDE","Reserved for future IDE/sandbox" in (be/"app/services/vision_app/runtime.py").read_text()),
 ("Working scope combobox","SCOPE INSPECTOR" in (fe/"src/components/ComputerVision/WorkingModulePanel.tsx").read_text()),
 ("Decision Edit removed","Decision / Glue" in (fe/"src/components/ComputerVision/WorkingModulePanel.tsx").read_text()),
 ("Lazy Debug Workspace",(fe/"src/components/ComputerVision/DebugWorkspace.tsx").exists()),
 ("IOT IDE viewport",(fe/"src/components/ComputerVision/IotIdePlaceholder.tsx").exists()),
 ("Camera live preview","Live preview" in (fe/"src/components/ComputerVision/CameraModulePanel.tsx").read_text()),
 ("Explicit Original Master","Original Master" in (fe/"src/components/ComputerVision/MasterSamplePanel.tsx").read_text()),
 ("OK/NG only Working","module==='working'&&run" in (fe/"src/Pages/ComputerVisionPage.tsx").read_text()),
 ("v0.9 handoff MD",(fe/"docs/llm_context/updates/v0900_computer_vision_control_workspace.md").exists()),
 ("Context generator v0.9","Control Mapper" in (fe/"tools/generate_llm_context_map.py").read_text()),]
 for label,ok in checks:print(f"[{'OK' if ok else 'FAIL'}] {label}");fail += 0 if ok else 1
 py=[rpath(fe,be,v) for v in list(MODIFIED)+list(CREATED) if v.startswith("backend/") and v.endswith(".py")]
 try:
  for p in py:py_compile.compile(str(p),doraise=True)
  print(f"[OK] Python syntax ({len(py)} changed/new backend files)")
 except Exception as e:print("[FAIL] Python syntax",e);fail+=1
 targets=["tests/vision_app/test_vision_app_frame_v0100.py","tests/vision_app/test_vision_app_v0800.py","tests/vision_app/test_vision_app_v0801.py","tests/vision_app/test_vision_app_v0900.py"]
 existing=[x for x in targets if (be/x).exists()]
 p=subprocess.run([sys.executable,"-m","pytest","-q",*existing],cwd=str(be),text=True,capture_output=True)
 if p.returncode==0:print("[OK] Vision App regression tests");print(p.stdout.strip())
 else:print("[FAIL] Vision App regression tests");print((p.stdout+"\n"+p.stderr).strip());fail+=1
 if not skip and (fe/"node_modules").exists():
  p=subprocess.run(["npm","run","build"],cwd=str(fe))
  if p.returncode==0:print("[OK] Frontend npm build")
  else:print("[FAIL] Frontend npm build");fail+=1
 else:print("[SKIP] Frontend npm build")
 try:regen(fe,be);print("[OK] Regenerated LLM context docs")
 except Exception as e:print("[FAIL] Context regeneration",e);fail+=1
 if fail:print(f"[FAIL] v0.9.0 verification finished with {fail} issue(s).");return 1
 print("[OK] Computer Vision v0.9.0 verified.");return 0

def main():
 p=argparse.ArgumentParser();p.add_argument("command",choices=["scan","apply","verify"]);p.add_argument("--frontend");p.add_argument("--backend");p.add_argument("--skip-build",action="store_true");a=p.parse_args()
 try:
  fe,be=roots(a.frontend,a.backend)
  if a.command=="scan":return scan(fe,be)
  if a.command=="apply":return apply(fe,be)
  return verify(fe,be,a.skip_build)
 except Exception as e:print("[ERROR]",e);return 2
if __name__=="__main__":raise SystemExit(main())
